[CmdletBinding()]
param([switch]$Execute,[string]$ApprovalPhrase)
$ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'production_update_common.ps1'); Assert-ProductionTarget; Assert-Approval $Execute $ApprovalPhrase 'CONFIGURE_OTG_REFRESH_8502'; $tasks=@('OTG_Derived_Data_Refresh_Production','OTG_Metadata_Refresh_Production'); "MODE=$(if($Execute){'EXECUTE'}else{'DRY_RUN'})"; 'PRODUCTION_REFRESH_TASK_COLLISION_POLICY=FAIL_CLOSED'; 'TASKS=OTG_Derived_Data_Refresh_Production,OTG_Metadata_Refresh_Production'; 'DERIVED_TRIGGER=EVERY_15_MINUTES'; 'METADATA_TRIGGER=EVERY_60_MINUTES'; 'STAGING_TASKS_TOUCHED=NO'; Invoke-GuardedAction -Execute:$Execute -Name 'REGISTER_EXACT_PRODUCTION_REFRESH_TASKS' -Action { foreach($t in $tasks){throw 'TASK_REGISTRATION_REQUIRES_EXPLICIT_SERVER_EXECUTION_REVIEW'} }; "MUTATION_EXECUTED=$(if($Execute){'YES'}else{'NO'})"
